alter table public.noticias add column if not exists secciones jsonb not null default '[]'::jsonb;
alter table public.noticias add column if not exists galeria jsonb not null default '[]'::jsonb;

insert into public.noticias
  (titulo, slug, subtitulo, resumen, contenido, imagen_url, tipo, fecha_evento, lugar, organizacion, secciones, galeria, temario, activo)
select
  'Loja abre una ruta hacia el mundo',
  'loja-exporta-2026-ruta-hacia-el-mundo',
  'Loja Exporta 2026 y el impulso digital de Lojanova',
  'Dos jornadas conectaron a más de 80 productores lojanos con delegaciones, cámaras y aliados internacionales, y abrieron una agenda de seguimiento que continúa en el entorno digital.',
  'Loja se convirtió, el 30 y 31 de julio de 2026, en un punto de encuentro entre la producción local y una red internacional de embajadas, cámaras y empresas. Más de 80 productores presentaron café, alimentos, artesanías y otras expresiones del territorio ante actores capaces de abrir conversaciones, aportar conocimiento y acercar nuevos mercados.',
  'assets/noticias/loja-exporta-2026/portada-productores.webp',
  'rueda_negocios',
  '2026-07-31',
  'Teatro Benjamín Carrión, Loja',
  'Iniciativa impulsada por la Prefectura de Loja para acercar la oferta productiva provincial a nuevos mercados y redes de cooperación internacional.',
  '[{"titulo":"Una rueda de negocios con acento internacional","contenido":"La representación internacional incluyó a las embajadas de India, Corea del Sur, China, Italia y Bulgaria; a las Eurocámaras de Italia, Francia, Alemania y Bulgaria; y a la Cámara de Shanghái. Cada mercado aportó requisitos, lenguajes comerciales y oportunidades distintas para la oferta lojana."},{"titulo":"La conducción detrás del encuentro","contenido":"Loja Exporta 2026 fue impulsada por el prefecto Mario Mancino y dirigida por el Mgs. Santiago Idrobo, coordinador de Cooperación Internacional. La coordinación permitió reunir a diez cooperantes internacionales planteados como aliados para acompañar procesos posteriores al evento."},{"titulo":"Cuando el producto cuenta la historia del territorio","contenido":"Degustaciones, empaques, relatos de origen y demostraciones hicieron tangible la conversación comercial. La calidad, la identidad y el origen de cada producto se convirtieron en cartas de presentación de la provincia."},{"titulo":"El día después de la rueda de negocios","contenido":"El reto continúa con talleres gratuitos, seguimiento de contactos, actualización de información productiva y acompañamiento técnico. Registrar intereses, requisitos y acciones pendientes es esencial para convertir la visibilidad en oportunidades verificables."},{"titulo":"De Loja a Shanghái","contenido":"Tras el encuentro, una selección de productos presentados en Loja Exporta 2026 llegó a Shanghái. La misión, encabezada por Santiago Idrobo, incluyó una visita al Consulado General del Ecuador y extendió la conversación hacia uno de los principales centros económicos de Asia."},{"titulo":"Lojanova: la vitrina que prolonga el encuentro","contenido":"Lojanova mantiene disponible la oferta de productos, categorías, cantones y perfiles de emprendedores. No funciona como tienda en línea: organiza la oferta, fortalece la identidad de origen y facilita el descubrimiento y el contacto directo."},{"titulo":"La arquitectura digital de Lojanova","contenido":"José Valverde ideó y desarrolló la plataforma desde la conceptualización hasta su estructura, diseño, funcionalidades y propuesta de posicionamiento. El proyecto integró herramientas web, bases de datos y sistemas de administración para gestionar productos, emprendedores, noticias y contenidos."},{"titulo":"El pulso digital","contenido":"Entre el 25 de julio y el 8 de agosto de 2026, los quince valores visibles del panel sumaron 1.234 visitas. El pico fue de 209 visitas el 3 de agosto. Ecuador encabezó los registros visibles y también aparecieron señales desde Estados Unidos, España, Francia, China, Vietnam y Corea del Sur."},{"titulo":"El producto concreto ganó la conversación","contenido":"Cuatro publicaciones verificadas el 8 de agosto reunieron 487 acciones públicas observables: 402 en Facebook y 85 en Instagram. Un reel sobre café concentró 297 acciones visibles. Estas métricas muestran atención y respuesta pública, pero no equivalen a personas únicas ni permiten afirmar cuántas ventas, acuerdos o exportaciones se produjeron."},{"titulo":"Una agenda que continúa","contenido":"El encuentro instaló relaciones, la plataforma prolongó la visibilidad y los datos señalaron dónde existe atención. La siguiente etapa debe medirse en contactos atendidos, capacidades fortalecidas y oportunidades que avanzan con responsables y plazos definidos."}]'::jsonb,
  '[{"url":"assets/noticias/loja-exporta-2026/encuentro-institucional.webp","descripcion":"La jornada institucional reunió a delegaciones, autoridades, productores y aliados en el Teatro Benjamín Carrión."},{"url":"assets/noticias/loja-exporta-2026/artesania-lojana.webp","descripcion":"La artesanía mostró tradición, oficio e identidad territorial."},{"url":"assets/noticias/loja-exporta-2026/productos-lojanos.webp","descripcion":"Productos lojanos formaron parte de la vitrina comercial del encuentro."},{"url":"assets/noticias/loja-exporta-2026/degustacion-productos.webp","descripcion":"Las degustaciones acercaron la oferta productiva a visitantes y delegaciones."},{"url":"assets/noticias/loja-exporta-2026/delegaciones-participantes.webp","descripcion":"Delegaciones, autoridades y productores al cierre de la jornada."},{"url":"assets/noticias/loja-exporta-2026/mision-shanghai.webp","descripcion":"La agenda posterior llevó una muestra de la oferta lojana hasta Shanghái."},{"url":"assets/noticias/loja-exporta-2026/consulado-shanghai.webp","descripcion":"La misión incluyó una visita al Consulado General del Ecuador en Shanghái."},{"url":"assets/noticias/loja-exporta-2026/plataforma-lojanova.webp","descripcion":"Lojanova prolonga digitalmente la visibilidad de la oferta productiva provincial."},{"url":"assets/noticias/loja-exporta-2026/jose-valverde.webp","descripcion":"José Valverde, experto en Negocios Internacionales e impulsor del desarrollo de Lojanova."},{"url":"assets/noticias/loja-exporta-2026/visitas-diarias.webp","descripcion":"Serie visible de visitas diarias entre el 25 de julio y el 8 de agosto de 2026."},{"url":"assets/noticias/loja-exporta-2026/visitantes-pais.webp","descripcion":"Visitantes por país en las filas visibles del panel analizado."},{"url":"assets/noticias/loja-exporta-2026/visitantes-ciudad.webp","descripcion":"Visitantes por ciudad en las filas visibles del panel analizado."},{"url":"assets/noticias/loja-exporta-2026/respuesta-publica.webp","descripcion":"Respuesta pública observable en cuatro publicaciones verificadas."}]'::jsonb,
  '[]'::jsonb,
  true
where not exists (
  select 1 from public.noticias where slug = 'loja-exporta-2026-ruta-hacia-el-mundo'
);
